python3 -c "
import csv

totals = {}
with open('/data/sales.csv', mode='r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        region = row['region'].strip()
        amount_str = row['amount'].strip()
        # amount might be int or float
        try:
            amount = float(amount_str)
        except ValueError:
            continue
        totals[region] = totals.get(region, 0.0) + amount

# Check if amounts are ints or floats
sorted_totals = sorted(totals.items(), key=lambda x: x[1], reverse=True)
for r, t in sorted_totals:
    # Check formatting: int vs float or as is
    if t.is_integer():
        print(f'{r}: {int(t)}')
    else:
        print(f'{r}: {t}')
"

